# Writes per-trade-vectors.txt: the per-trade (round-up and fixed) numbers that
# programs/sip-vault/src/per_trade.rs and scripts/per-trade.ts are both held to.
#
# COMPUTED FROM THE FORMULAS ALONE, with Python's unbounded integers and exact
# fractions, so a mistake the Rust and the TypeScript share (an overflow, a
# floor where a ceiling belongs) cannot also be in these numbers. The formulas
# are the ADR's (scaling ADR §5.2.4 and §5.2.5):
#   X = floor(x * p / 1e9)                      the trade's worth, micro-dollars
#   r = min((u - X mod u) mod u, X)             u = unit_cents * 1e4
#   lamports = floor(r * 1e9 / p)
#   bound = count * ceil(u * 1e9 / price_min)
#   floor holds  <=>  2 * price_min * 1e-6 >= pyth_price * 10^expo  (exactly)
#
#   python3 -I tests/fixtures/per-trade-vectors.py > tests/fixtures/per-trade-vectors.txt
import hashlib
import struct
from fractions import Fraction


def roundup(x, p, unit_cents):
    u = unit_cents * 10_000
    worth = x * p // 10**9
    r = min((u - worth % u) % u, worth)
    return worth, r, r * 10**9 // p


def bound(count, unit_cents, price_min):
    u = unit_cents * 10_000
    return count * -(-(u * 10**9) // price_min)


def floor_holds(price_min, price, expo):
    return price > 0 and Fraction(2 * price_min, 10**6) >= Fraction(price) * Fraction(10) ** expo


def prices_hash(trades):
    h = hashlib.sha256()
    for _slot, signature, price in sorted(trades, key=lambda t: (t[0], t[1])):
        h.update(signature + struct.pack("<Q", price))
    return h.hexdigest()


print("# GENERATED by per-trade-vectors.py from the formulas in its header. Do not edit by hand.")
print("# roundup x_lamports price_usd_e6 unit_cents worth_usd_e6 roundup_usd_e6 lamports")
for x, p, unit in [
    (10_666_667, 150_000_000, 100),  # the owner's $1.60 at $150 saves $0.40
    (16_000_000, 125_000_000, 100),  # an exact $2.00 saves 0
    (13_333_333, 150_000_000, 100),  # a "$2.00" worth 1,999,999 micro-dollars saves 6 lamports
    (1_000_000, 150_000_000, 100),  # $0.15: the round-up stops at the trade itself
    (0, 150_000_000, 100),
    (10_666_667, 1_500_000, 100),  # the scale bug: a price 100x too low charges 100 %
    (50_000_000, 146_000_000, 500),  # $7.30 to the next $5
    (1_000_000_000_000, 150_123_456, 1_000),  # 1000 SOL to the next $10
    (18_446_744_073_709_551_615, 1_000_000_000_000, 10_000),  # x * p and the worth pass u64
    (99_999_999, 100_000_000, 100),
    (1, 1, 100),
]:
    worth, r, lamports = roundup(x, p, unit)
    assert lamports <= x
    print("roundup", x, p, unit, worth, r, lamports)

print("# bound trade_count unit_cents price_min_usd_e6 bound_lamports")
for count, unit, price_min in [
    (1, 100, 150_000_000),
    (1, 100, 1_500_000),
    (3, 500, 146_000_000),
    (0, 100, 150_000_000),
    (4_294_967_295, 10_000, 1),
    (2, 100, 3),
]:
    print("bound", count, unit, price_min, bound(count, unit, price_min))

print("# floor price_min_usd_e6 pyth_price pyth_expo holds")
for price_min, price, expo in [
    (75_000_000, 15_000_000_000, -8),
    (74_999_999, 15_000_000_000, -8),
    (1_500_000, 15_000_000_000, -8),
    (150_000_000, 15_000_000_000, -8),
    (51_296_606, 10_259_321_149, -8),
    (51_296_605, 10_259_321_149, -8),
    (75_000_000, 15_000_000, -5),
    (74_999_999, 15_000_000, -5),
    (75_000_000, 150, 0),
    (74_999_999, 150, 0),
    (18_446_744_073_709_551_615, 9_223_372_036_854_775_807, 18),
    (1, 0, -8),
    (1, -5, -8),
]:
    print("floor", price_min, price, expo, 1 if floor_holds(price_min, price, expo) else 0)

print("# priceshash name sha256_hex  (trades: (slot, signature bytes, price_usd_e6); ordered by slot, then signature bytes)")
one, two = bytes([0x11]) * 64, bytes([0x22]) * 64
print("priceshash empty", prices_hash([]))
print("priceshash one", prices_hash([(500, one, 150_000_000)]))
print("priceshash two_slots", prices_hash([(501, one, 151_234_567), (500, two, 150_000_000)]))
print("priceshash two_same_slot", prices_hash([(500, two, 150_000_000), (500, one, 151_234_567)]))
